insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('4989cd8c-2e2d-4f5a-bd9a-0e611bef7efb', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'National Income Accounting: GDP, GNP, GNI, and Macro Data', 'This unit teaches students how economists measure the size and composition of an economy. It turns broad claims about the economy into concrete, comparable indicators.', 0),
  ('19985e6c-9d08-4b9f-8902-33522051dea2', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '4989cd8c-2e2d-4f5a-bd9a-0e611bef7efb', 'subtopic'::public.curated_course_node_type, 'GDP and output measurement', 'Students learn what GDP counts and why it is the central measure of production. The gist is that GDP is useful but incomplete.', 0),
  ('27228acf-f7ad-4d1f-ae7a-0b6a77ab2da0', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '19985e6c-9d08-4b9f-8902-33522051dea2', 'concept'::public.curated_course_node_type, 'Final goods and services', null, 0),
  ('2a58bb27-0906-43f2-9058-2fcc6201d76e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '19985e6c-9d08-4b9f-8902-33522051dea2', 'concept'::public.curated_course_node_type, 'Market value and production within borders', null, 1),
  ('3ab60089-65ee-49cd-ace2-409cdf395277', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '19985e6c-9d08-4b9f-8902-33522051dea2', 'concept'::public.curated_course_node_type, 'Expenditure approach: C + I + G + NX', null, 2),
  ('9f3a8e9b-1410-4fb6-ae8d-6e3ea30e47c0', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '19985e6c-9d08-4b9f-8902-33522051dea2', 'concept'::public.curated_course_node_type, 'Value-added approach', null, 3),
  ('0f50c16d-5f23-4e38-a571-65121851b20b', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '4989cd8c-2e2d-4f5a-bd9a-0e611bef7efb', 'subtopic'::public.curated_course_node_type, 'GNP, GNI, and income concepts', 'These measures clarify the difference between production in a place and income earned by a country''s residents. This matters for global business and cross-country comparison.', 1),
  ('39023a97-8bcc-435c-b750-eba6a2acc93e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '0f50c16d-5f23-4e38-a571-65121851b20b', 'concept'::public.curated_course_node_type, 'Gross national product', null, 0),
  ('5defdd57-2ab0-4e94-b896-dee62c21f31a', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '0f50c16d-5f23-4e38-a571-65121851b20b', 'concept'::public.curated_course_node_type, 'Gross national income', null, 1),
  ('51c73817-09ab-4678-8372-db4a67237f9c', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '0f50c16d-5f23-4e38-a571-65121851b20b', 'concept'::public.curated_course_node_type, 'Net factor income from abroad', null, 2),
  ('a67f31af-a9a9-41c9-baf1-4298ffa4ae47', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '0f50c16d-5f23-4e38-a571-65121851b20b', 'concept'::public.curated_course_node_type, 'Why multinational activity complicates measurement', null, 3),
  ('5dbbda53-a332-4132-ba20-eeb1b3e3bfa7', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '4989cd8c-2e2d-4f5a-bd9a-0e611bef7efb', 'subtopic'::public.curated_course_node_type, 'Nominal versus real values', 'Students learn to separate price changes from quantity changes. This is the key to interpreting growth over time.', 2),
  ('84fe6b95-73ab-4229-bb57-4470d5b83344', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5dbbda53-a332-4132-ba20-eeb1b3e3bfa7', 'concept'::public.curated_course_node_type, 'Nominal GDP', null, 0),
  ('904abebc-5396-48de-ac52-7f921a7759b5', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5dbbda53-a332-4132-ba20-eeb1b3e3bfa7', 'concept'::public.curated_course_node_type, 'Real GDP', null, 1),
  ('93b73424-0074-424c-887b-55990b56efed', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5dbbda53-a332-4132-ba20-eeb1b3e3bfa7', 'concept'::public.curated_course_node_type, 'GDP deflator', null, 2),
  ('a3c72f74-d843-4dc3-b31d-f7a763330cc9', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5dbbda53-a332-4132-ba20-eeb1b3e3bfa7', 'concept'::public.curated_course_node_type, 'Base years and index numbers', null, 3),
  ('682ef01d-a67a-474d-b43a-98704f1d595e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '4989cd8c-2e2d-4f5a-bd9a-0e611bef7efb', 'subtopic'::public.curated_course_node_type, 'Using macro data responsibly', 'Macro data are estimates built from definitions, surveys, and revisions. Students learn to read data with precision rather than false certainty.', 3),
  ('40418492-cd26-4af2-a68a-59bb32277551', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '682ef01d-a67a-474d-b43a-98704f1d595e', 'concept'::public.curated_course_node_type, 'Per-capita measures', null, 0),
  ('50727d4f-3079-4f52-ae5a-2420a2a085e5', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '682ef01d-a67a-474d-b43a-98704f1d595e', 'concept'::public.curated_course_node_type, 'Seasonal adjustment', null, 1),
  ('0ba052c1-3e3c-43d3-812a-a784883d6514', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '682ef01d-a67a-474d-b43a-98704f1d595e', 'concept'::public.curated_course_node_type, 'Data revisions', null, 2),
  ('59e26f5e-19fa-4eb1-aa6f-306acabd72e0', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '682ef01d-a67a-474d-b43a-98704f1d595e', 'concept'::public.curated_course_node_type, 'Limits of GDP: household work, inequality, environment, and well-being', null, 3),
  ('5db4a939-790b-4f6b-8327-f867cfddd02b', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'Inflation, CPI, Unemployment, and the Phillips Curve', 'This unit covers the macro indicators people feel most directly: prices and jobs. Students learn how inflation and unemployment are measured and why they create policy tradeoffs.', 1),
  ('49c1eec0-79f0-4022-baae-9b75ead9ab0e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5db4a939-790b-4f6b-8327-f867cfddd02b', 'subtopic'::public.curated_course_node_type, 'Inflation and price indexes', 'Inflation measures the rate at which the general price level rises. The point is to distinguish broad inflation from changes in one price.', 0),
  ('e6a56d32-7aca-4ffa-8297-4739880ab27e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c1eec0-79f0-4022-baae-9b75ead9ab0e', 'concept'::public.curated_course_node_type, 'Consumer Price Index', null, 0),
  ('db3ca5d4-448a-49ea-93f5-e0de96de83b4', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c1eec0-79f0-4022-baae-9b75ead9ab0e', 'concept'::public.curated_course_node_type, 'Producer Price Index', null, 1),
  ('efe181bd-dda0-4b3e-a250-7a777212f024', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c1eec0-79f0-4022-baae-9b75ead9ab0e', 'concept'::public.curated_course_node_type, 'GDP deflator', null, 2),
  ('21302598-9cff-4e23-a959-58625b6f4dcb', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c1eec0-79f0-4022-baae-9b75ead9ab0e', 'concept'::public.curated_course_node_type, 'Core versus headline inflation', null, 3),
  ('900b940d-d3f5-435e-9867-afd70beafd5e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5db4a939-790b-4f6b-8327-f867cfddd02b', 'subtopic'::public.curated_course_node_type, 'Costs and causes of inflation', 'Students learn why inflation matters even when wages and prices both change. The gist is that inflation redistributes purchasing power and can distort decisions.', 1),
  ('696bb649-0d88-49f5-8c57-46a41ff2e0c5', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '900b940d-d3f5-435e-9867-afd70beafd5e', 'concept'::public.curated_course_node_type, 'Purchasing power', null, 0),
  ('172953e2-6c50-4e31-a818-fd6e142ec824', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '900b940d-d3f5-435e-9867-afd70beafd5e', 'concept'::public.curated_course_node_type, 'Menu costs and shoe-leather costs', null, 1),
  ('3ebb4eac-89e9-420e-abb3-7f00201a2eb8', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '900b940d-d3f5-435e-9867-afd70beafd5e', 'concept'::public.curated_course_node_type, 'Unexpected inflation and debtors/creditors', null, 2),
  ('ee75b16c-750f-4676-a66a-99ed5a044023', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '900b940d-d3f5-435e-9867-afd70beafd5e', 'concept'::public.curated_course_node_type, 'Demand-pull and cost-push inflation', null, 3),
  ('62e7ae01-3e30-46eb-871e-f199694ae240', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5db4a939-790b-4f6b-8327-f867cfddd02b', 'subtopic'::public.curated_course_node_type, 'Unemployment measurement', 'Unemployment is a labor-market indicator, but it is not as simple as counting people without jobs. Students learn the definitions behind the headline rate.', 2),
  ('15de7f0b-c503-403c-aeb1-989c6a2437d7', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '62e7ae01-3e30-46eb-871e-f199694ae240', 'concept'::public.curated_course_node_type, 'Labor force', null, 0),
  ('e5b7fdaa-1aa2-4fc8-a32e-cd4713613036', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '62e7ae01-3e30-46eb-871e-f199694ae240', 'concept'::public.curated_course_node_type, 'Unemployment rate', null, 1),
  ('3e30b7c4-4ff3-44e8-9013-fa8d5b7284f4', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '62e7ae01-3e30-46eb-871e-f199694ae240', 'concept'::public.curated_course_node_type, 'Labor force participation', null, 2),
  ('e793fcd8-9e0c-4a90-989d-fea9da802b79', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '62e7ae01-3e30-46eb-871e-f199694ae240', 'concept'::public.curated_course_node_type, 'Underemployment and discouraged workers', null, 3),
  ('126055f3-332d-4124-a39a-4be9783ae09e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5db4a939-790b-4f6b-8327-f867cfddd02b', 'subtopic'::public.curated_course_node_type, 'Phillips curve intuition', 'The Phillips curve introduces the relationship between inflation and unemployment. Students learn why the short-run tradeoff can shift when expectations change.', 3),
  ('ce9f0dfe-fb2d-4b31-973f-c0c1e2498faf', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '126055f3-332d-4124-a39a-4be9783ae09e', 'concept'::public.curated_course_node_type, 'Short-run Phillips curve', null, 0),
  ('b75e9c22-e9f3-4cbd-89c1-61589f9dc364', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '126055f3-332d-4124-a39a-4be9783ae09e', 'concept'::public.curated_course_node_type, 'Inflation expectations', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('67e88280-dc78-411d-a428-1333cd27fcbd', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '126055f3-332d-4124-a39a-4be9783ae09e', 'concept'::public.curated_course_node_type, 'Natural rate of unemployment', null, 2),
  ('e8f23e89-933b-4bfa-981f-0d29e5ed6dd3', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '126055f3-332d-4124-a39a-4be9783ae09e', 'concept'::public.curated_course_node_type, 'Stagflation as a challenge to simple tradeoffs', null, 3),
  ('df4887ce-6a1e-4f51-8766-fb5a81b3cd7d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'Aggregate Demand and Aggregate Supply', 'This unit gives students the main framework for analyzing economy-wide fluctuations. It shows how spending, production capacity, prices, and output interact.', 2),
  ('61cfe082-8a60-413e-bf16-a29a57db0b15', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df4887ce-6a1e-4f51-8766-fb5a81b3cd7d', 'subtopic'::public.curated_course_node_type, 'Aggregate demand', 'Aggregate demand represents planned spending across the economy. Students learn why consumption, investment, government spending, and net exports move together with the price level.', 0),
  ('164372f4-4a67-4274-933e-22e80e3c56ef', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '61cfe082-8a60-413e-bf16-a29a57db0b15', 'concept'::public.curated_course_node_type, 'Components of AD', null, 0),
  ('1fee2694-2c7f-484d-b1ac-4b105cc90069', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '61cfe082-8a60-413e-bf16-a29a57db0b15', 'concept'::public.curated_course_node_type, 'Wealth effect', null, 1),
  ('79dd4de4-0a63-4ac9-9643-bbafa55780d2', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '61cfe082-8a60-413e-bf16-a29a57db0b15', 'concept'::public.curated_course_node_type, 'Interest-rate effect', null, 2),
  ('3132d52a-d59d-4e5c-b42d-7903584bf77d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '61cfe082-8a60-413e-bf16-a29a57db0b15', 'concept'::public.curated_course_node_type, 'Exchange-rate effect', null, 3),
  ('fca2bac8-f10c-4b76-94cb-e15e71942194', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df4887ce-6a1e-4f51-8766-fb5a81b3cd7d', 'subtopic'::public.curated_course_node_type, 'Short-run aggregate supply', 'Short-run aggregate supply explains why output can rise or fall with prices before wages and expectations fully adjust.', 1),
  ('065c5072-cee3-45b1-9191-57127ae562a3', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'fca2bac8-f10c-4b76-94cb-e15e71942194', 'concept'::public.curated_course_node_type, 'Sticky wages and prices', null, 0),
  ('b3dcede2-5c9b-4f53-8c89-2f4bf4f6851e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'fca2bac8-f10c-4b76-94cb-e15e71942194', 'concept'::public.curated_course_node_type, 'Input costs', null, 1),
  ('c2da711b-1ddd-4232-b56a-d350ebec3010', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'fca2bac8-f10c-4b76-94cb-e15e71942194', 'concept'::public.curated_course_node_type, 'Productivity shocks', null, 2),
  ('58687974-8175-4350-95d1-63dd22690c5e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'fca2bac8-f10c-4b76-94cb-e15e71942194', 'concept'::public.curated_course_node_type, 'Supply shocks', null, 3),
  ('88d50c00-4619-457c-a009-57a346cd9cc1', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df4887ce-6a1e-4f51-8766-fb5a81b3cd7d', 'subtopic'::public.curated_course_node_type, 'Long-run aggregate supply', 'Long-run supply reflects productive capacity rather than short-run demand. Students learn the difference between temporary fluctuations and potential output.', 2),
  ('9b256e70-8539-4e72-8872-c3e233b3941b', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '88d50c00-4619-457c-a009-57a346cd9cc1', 'concept'::public.curated_course_node_type, 'Potential GDP', null, 0),
  ('53f798dd-24e9-4879-a169-29fa928d3d6a', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '88d50c00-4619-457c-a009-57a346cd9cc1', 'concept'::public.curated_course_node_type, 'Full-employment output', null, 1),
  ('86188d4d-b46b-4e00-9362-a3ce8b75c5cf', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '88d50c00-4619-457c-a009-57a346cd9cc1', 'concept'::public.curated_course_node_type, 'Natural rate concepts', null, 2),
  ('9c8d239a-c48c-4da2-b550-9bd081b8df87', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '88d50c00-4619-457c-a009-57a346cd9cc1', 'concept'::public.curated_course_node_type, 'Shifts from labor, capital, technology, and institutions', null, 3),
  ('f8c253b4-17d4-48c3-9b23-96b3637268be', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df4887ce-6a1e-4f51-8766-fb5a81b3cd7d', 'subtopic'::public.curated_course_node_type, 'AD-AS equilibrium', 'The AD-AS model connects inflation, unemployment, growth, and policy in one diagram. Students use it to reason through recessions, booms, and shocks.', 3),
  ('394012ca-85a2-4f0b-bfaf-ecd23148d6c2', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'f8c253b4-17d4-48c3-9b23-96b3637268be', 'concept'::public.curated_course_node_type, 'Short-run equilibrium', null, 0),
  ('d61121d1-a827-4580-bbc0-16f0ddb0c251', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'f8c253b4-17d4-48c3-9b23-96b3637268be', 'concept'::public.curated_course_node_type, 'Recessionary gap', null, 1),
  ('5d21e90e-396e-42a7-ac1c-c44acc1d57d4', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'f8c253b4-17d4-48c3-9b23-96b3637268be', 'concept'::public.curated_course_node_type, 'Inflationary gap', null, 2),
  ('5a0e3387-a3a8-40c3-969f-3fd252e4140d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'f8c253b4-17d4-48c3-9b23-96b3637268be', 'concept'::public.curated_course_node_type, 'Demand shocks versus supply shocks', null, 3),
  ('e37bf733-3870-4bfd-9846-f3810938a5da', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'Fiscal Policy and Government Budgets', 'Fiscal policy shows how government spending and taxation influence aggregate demand, distribution, debt, and long-run capacity. Students learn both the power and constraints of budget policy.', 3),
  ('b11d4ef1-256e-4353-b8c6-880333f8e115', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'e37bf733-3870-4bfd-9846-f3810938a5da', 'subtopic'::public.curated_course_node_type, 'Government spending and taxes', 'Students learn the main tools of fiscal policy. The gist is that changes in spending and taxes alter demand and incentives.', 0),
  ('e6a3136a-cf0f-465b-bb50-10a96dd3ac80', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'b11d4ef1-256e-4353-b8c6-880333f8e115', 'concept'::public.curated_course_node_type, 'Government purchases', null, 0),
