  ('f82320db-a3eb-4512-b724-37e04072dc77', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'b11d4ef1-256e-4353-b8c6-880333f8e115', 'concept'::public.curated_course_node_type, 'Tax rates and tax bases', null, 2),
  ('c4b52ef5-6076-4a8e-b41e-4c5e78e08ba6', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'b11d4ef1-256e-4353-b8c6-880333f8e115', 'concept'::public.curated_course_node_type, 'Automatic stabilizers', null, 3),
  ('c30f47a4-95fd-41a6-87b3-51927c8ac9cf', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'e37bf733-3870-4bfd-9846-f3810938a5da', 'subtopic'::public.curated_course_node_type, 'Multipliers', 'Multipliers explain why one dollar of spending or tax change can have a larger or smaller effect on GDP. Students learn why context matters.', 1),
  ('13e0b6df-8c67-4ddc-9d11-54cbe2f76031', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'c30f47a4-95fd-41a6-87b3-51927c8ac9cf', 'concept'::public.curated_course_node_type, 'Marginal propensity to consume', null, 0),
  ('616f3080-e927-4070-93cf-b403e75c5754', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'c30f47a4-95fd-41a6-87b3-51927c8ac9cf', 'concept'::public.curated_course_node_type, 'Spending multiplier', null, 1),
  ('9e471ef8-90c2-44d5-82a2-df168dea153a', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'c30f47a4-95fd-41a6-87b3-51927c8ac9cf', 'concept'::public.curated_course_node_type, 'Tax multiplier', null, 2),
  ('731c2ec1-1350-48b5-be84-85f3e642b737', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'c30f47a4-95fd-41a6-87b3-51927c8ac9cf', 'concept'::public.curated_course_node_type, 'Crowding out and leakages', null, 3),
  ('17a98e25-b427-461d-a3dd-15bd5c026de0', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'e37bf733-3870-4bfd-9846-f3810938a5da', 'subtopic'::public.curated_course_node_type, 'Deficits and debt', 'Students learn how budget flows become accumulated debt. The goal is to separate short-run stabilization from long-run sustainability.', 2),
  ('f977ffa5-3afc-4a0a-9101-325ad1467c57', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '17a98e25-b427-461d-a3dd-15bd5c026de0', 'concept'::public.curated_course_node_type, 'Budget deficit versus national debt', null, 0),
  ('81d75c0e-2a88-4c57-be22-ff9073b2a53c', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '17a98e25-b427-461d-a3dd-15bd5c026de0', 'concept'::public.curated_course_node_type, 'Debt-to-GDP ratio', null, 1),
  ('18d8fbd2-2df0-4f59-877c-2bc34de680e4', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '17a98e25-b427-461d-a3dd-15bd5c026de0', 'concept'::public.curated_course_node_type, 'Interest payments', null, 2),
  ('d8b0d7de-49a8-488c-87e1-f65099ea0299', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '17a98e25-b427-461d-a3dd-15bd5c026de0', 'concept'::public.curated_course_node_type, 'Primary deficit', null, 3),
  ('88cb1e23-852e-452d-8823-8a7dc2961b09', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'e37bf733-3870-4bfd-9846-f3810938a5da', 'subtopic'::public.curated_course_node_type, 'Fiscal policy evaluation', 'Students learn to judge fiscal policy by timing, targeting, incentives, and tradeoffs. This prepares them for real policy debates.', 3);
