  ('98524457-a2ac-4090-b560-813e99485eed', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'Monetary Policy and Central Banks', 'This unit explains how central banks influence interest rates, financial conditions, inflation, and output. Students learn why money is a policy tool, not just a medium of exchange.', 4),
  ('c3f16e49-5b39-4a85-9dae-a5772368eb77', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '98524457-a2ac-4090-b560-813e99485eed', 'subtopic'::public.curated_course_node_type, 'Central bank roles', 'Students learn what central banks do and why independence and credibility matter. The gist is that central banks manage the monetary and financial environment.', 0),
  ('46d1b8bb-63dd-4702-86dd-47aaf2cc8eee', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'c3f16e49-5b39-4a85-9dae-a5772368eb77', 'concept'::public.curated_course_node_type, 'Price stability', null, 0),
