  ('49c827aa-d5da-4706-87e6-c1bfa8b0b003', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '98524457-a2ac-4090-b560-813e99485eed', 'subtopic'::public.curated_course_node_type, 'Policy instruments', 'Students learn the tools central banks use to affect interest rates and liquidity. This connects classroom models to actual institutions.', 1),
  ('24912189-b458-44d6-9620-69dfbf3464f3', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c827aa-d5da-4706-87e6-c1bfa8b0b003', 'concept'::public.curated_course_node_type, 'Policy interest rates', null, 0),
