  ('b736c006-da1a-4a19-bba2-c0a049e77734', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c827aa-d5da-4706-87e6-c1bfa8b0b003', 'concept'::public.curated_course_node_type, 'Reserve requirements', null, 2),
  ('2d0c4728-f2b5-43f5-b2b1-77638bd4bbf4', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c827aa-d5da-4706-87e6-c1bfa8b0b003', 'concept'::public.curated_course_node_type, 'Discount window', null, 3),
  ('9441ad2a-8983-4b3a-bd1f-3aa2c2c7a013', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '49c827aa-d5da-4706-87e6-c1bfa8b0b003', 'concept'::public.curated_course_node_type, 'Quantitative easing', null, 4),
  ('fcc34206-758b-47c7-883e-44687f24725f', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '98524457-a2ac-4090-b560-813e99485eed', 'subtopic'::public.curated_course_node_type, 'Monetary transmission', 'Transmission explains how a policy-rate change moves through the economy. Students learn why effects are indirect and uncertain.', 2),
  ('bcc43bcb-7940-4276-bff1-1d1520281ddc', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'fcc34206-758b-47c7-883e-44687f24725f', 'concept'::public.curated_course_node_type, 'Interest-rate channel', null, 0),
