  ('a2bdbcc3-3aa3-4ada-a82b-58bfc9d55f2d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'fcc34206-758b-47c7-883e-44687f24725f', 'concept'::public.curated_course_node_type, 'Asset-price channel', null, 3),
  ('d28c9baf-4965-48df-afb1-aa24bd3e6165', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'fcc34206-758b-47c7-883e-44687f24725f', 'concept'::public.curated_course_node_type, 'Expectations channel', null, 4),
  ('86012301-127a-4b75-aed0-c34cee5de96d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '98524457-a2ac-4090-b560-813e99485eed', 'subtopic'::public.curated_course_node_type, 'Policy rules and judgment', 'Students learn how central banks balance systematic rules with changing conditions. This supports analysis of inflation targeting and crisis response.', 3),
  ('ad0c455d-9579-450d-ad9a-c2ef8ea6cbc8', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '86012301-127a-4b75-aed0-c34cee5de96d', 'concept'::public.curated_course_node_type, 'Taylor rule intuition', null, 0),
