  ('0e781d85-8a25-4f25-9c9c-b6c7f21920a5', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '86012301-127a-4b75-aed0-c34cee5de96d', 'concept'::public.curated_course_node_type, 'Forward guidance', null, 2),
  ('2433287f-6f27-4d45-a749-efdaf48206b9', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '86012301-127a-4b75-aed0-c34cee5de96d', 'concept'::public.curated_course_node_type, 'Zero lower bound constraints', null, 3),
  ('d4448ef6-5160-42d0-8500-029e114270ae', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'Money, Banking, and Financial Markets', 'This unit connects macroeconomics to the financial system. Students learn how banks, money creation, credit, and interest rates shape real economic activity.', 5),
  ('9d45fa02-9287-4f4d-8a46-6eab028328f4', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'd4448ef6-5160-42d0-8500-029e114270ae', 'subtopic'::public.curated_course_node_type, 'Functions and measures of money', 'Money lowers transaction costs and supports pricing, saving, and exchange. Students learn why economists define money in several ways.', 0),
  ('cd8951d6-5f72-43b9-b62c-3123ea17b86f', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9d45fa02-9287-4f4d-8a46-6eab028328f4', 'concept'::public.curated_course_node_type, 'Medium of exchange', null, 0),
