  ('d223a005-66db-4d41-b8a7-9a8193fca3dc', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9d45fa02-9287-4f4d-8a46-6eab028328f4', 'concept'::public.curated_course_node_type, 'Store of value', null, 2),
  ('fea159cf-0233-4830-a6c8-2adaa5c98056', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9d45fa02-9287-4f4d-8a46-6eab028328f4', 'concept'::public.curated_course_node_type, 'M1 and M2', null, 3),
  ('2edc70e4-0d90-4746-aafc-887c3e706561', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'd4448ef6-5160-42d0-8500-029e114270ae', 'subtopic'::public.curated_course_node_type, 'Banks and money creation', 'Students learn how deposits and lending expand the money supply. The point is to understand banking as a balance-sheet system.', 1),
  ('9692fd77-ff76-445b-9289-3788c5c85f2b', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '2edc70e4-0d90-4746-aafc-887c3e706561', 'concept'::public.curated_course_node_type, 'Fractional reserves', null, 0),
