  ('cdcaf1e0-8c99-4145-8366-bf457cf3c436', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '2edc70e4-0d90-4746-aafc-887c3e706561', 'concept'::public.curated_course_node_type, 'Money multiplier intuition', null, 2),
  ('15e38a32-25d1-4d50-a63c-d2127b827d19', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '2edc70e4-0d90-4746-aafc-887c3e706561', 'concept'::public.curated_course_node_type, 'Bank capital and liquidity', null, 3),
