  ('546272c9-b4d8-46e1-a66d-bf7bf33b682a', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5f0cad5f-1ebf-4516-95c2-d89a39d6b4d6', 'concept'::public.curated_course_node_type, 'Nominal interest rates', null, 0);
