  ('3f236562-c7bc-4863-bfc9-6d0a744566a0', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5f0cad5f-1ebf-4516-95c2-d89a39d6b4d6', 'concept'::public.curated_course_node_type, 'Risk premiums', null, 3),
  ('6571e576-7b5a-45d3-9ddc-b394d0f2f483', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'd4448ef6-5160-42d0-8500-029e114270ae', 'subtopic'::public.curated_course_node_type, 'Financial instability', 'Students learn why finance can amplify booms and downturns. This creates a bridge to recession analysis and policy response.', 3),
  ('146bb872-6fa4-4eb3-a8f9-6e80683cd7cd', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '6571e576-7b5a-45d3-9ddc-b394d0f2f483', 'concept'::public.curated_course_node_type, 'Leverage', null, 0),
