  ('09c67f5c-d5ec-4d0f-9f5c-0e142343947b', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '6571e576-7b5a-45d3-9ddc-b394d0f2f483', 'concept'::public.curated_course_node_type, 'Credit crunches', null, 2),
  ('66d1b5fe-e420-4754-88f2-3480bc89ead0', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '6571e576-7b5a-45d3-9ddc-b394d0f2f483', 'concept'::public.curated_course_node_type, 'Systemic risk', null, 3),
  ('1f692c29-f136-4f93-815d-e47d017a9356', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '6571e576-7b5a-45d3-9ddc-b394d0f2f483', 'concept'::public.curated_course_node_type, 'Macroprudential regulation', null, 4),
  ('36388793-5ffe-4b17-8f77-3b6e18821923', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'Long-Run Economic Growth and Productivity', 'This unit asks why living standards rise over decades and why some countries grow faster than others. Students learn that long-run prosperity depends on productivity, capital, technology, and institutions.', 6),
  ('b935a0bc-8a48-4228-ad86-bdd7f497903f', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '36388793-5ffe-4b17-8f77-3b6e18821923', 'subtopic'::public.curated_course_node_type, 'Growth measurement', 'Students learn how to measure long-run improvements in living standards. The gist is that small growth-rate differences compound dramatically.', 0),
  ('5df52a6b-a47a-4675-9fae-7b54e3926acc', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'b935a0bc-8a48-4228-ad86-bdd7f497903f', 'concept'::public.curated_course_node_type, 'Real GDP per capita', null, 0),
  ('9161acc7-0460-4b9e-bc16-f5b4a3bf52d6', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'b935a0bc-8a48-4228-ad86-bdd7f497903f', 'concept'::public.curated_course_node_type, 'Growth rates', null, 1),
  ('bf910e20-493e-4139-8bfc-05be41b9cea8', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'b935a0bc-8a48-4228-ad86-bdd7f497903f', 'concept'::public.curated_course_node_type, 'Rule of 70', null, 2),
  ('ea09f47c-9c69-4693-a1a2-38da8cc40846', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'b935a0bc-8a48-4228-ad86-bdd7f497903f', 'concept'::public.curated_course_node_type, 'Convergence and divergence', null, 3),
  ('df05310c-2841-4c81-8c53-9846338f6276', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '36388793-5ffe-4b17-8f77-3b6e18821923', 'subtopic'::public.curated_course_node_type, 'Sources of growth', 'Students learn the main drivers of productive capacity. This turns growth from a mystery into a set of mechanisms.', 1),
  ('5fa17c78-723b-4fcc-af4a-088d2817b9ba', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df05310c-2841-4c81-8c53-9846338f6276', 'concept'::public.curated_course_node_type, 'Physical capital', null, 0),
