  ('6e4627c0-e387-490b-86da-10f1608fa270', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df05310c-2841-4c81-8c53-9846338f6276', 'concept'::public.curated_course_node_type, 'Technology', null, 2),
  ('a7f6eaad-0d80-455e-94dc-84a58b09d445', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df05310c-2841-4c81-8c53-9846338f6276', 'concept'::public.curated_course_node_type, 'Natural resources', null, 3),
  ('ac7b5de3-d553-4d40-b644-ba599cf9e19f', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'df05310c-2841-4c81-8c53-9846338f6276', 'concept'::public.curated_course_node_type, 'Institutions', null, 4),
  ('4c0334f2-d2aa-4ffa-a511-f07a839a61e3', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '36388793-5ffe-4b17-8f77-3b6e18821923', 'subtopic'::public.curated_course_node_type, 'Solow model intuition', 'The Solow model gives a simple framework for capital accumulation and steady-state growth. Students learn why investment alone cannot explain permanent growth.', 2),
  ('28bb12df-2d39-4abd-a4a3-34456593cc28', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '4c0334f2-d2aa-4ffa-a511-f07a839a61e3', 'concept'::public.curated_course_node_type, 'Capital deepening', null, 0),
