  ('6644d2dd-9993-48ec-888d-eae341f1addc', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '4c0334f2-d2aa-4ffa-a511-f07a839a61e3', 'concept'::public.curated_course_node_type, 'Steady state', null, 2),
  ('19a93455-57a9-40d7-84c7-cf288e3d0d9d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '4c0334f2-d2aa-4ffa-a511-f07a839a61e3', 'concept'::public.curated_course_node_type, 'Technological progress', null, 3),
  ('1683a7c5-ff35-46d7-8ac8-8bb1032c7b5e', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '36388793-5ffe-4b17-8f77-3b6e18821923', 'subtopic'::public.curated_course_node_type, 'Productivity and policy', 'Students learn how policy can support or hinder growth. The point is to connect macro outcomes to education, infrastructure, innovation, and governance.', 3),
  ('a408da98-b6d5-4586-8745-7d3f965992f5', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '1683a7c5-ff35-46d7-8ac8-8bb1032c7b5e', 'concept'::public.curated_course_node_type, 'Research and development', null, 0),
