  ('f26eebbd-57d9-4958-a7f3-ab28a18969b7', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '1683a7c5-ff35-46d7-8ac8-8bb1032c7b5e', 'concept'::public.curated_course_node_type, 'Openness to trade and ideas', null, 4),
  ('9ff88c17-4e2f-41e3-97c0-9244932bf8f1', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'Business Cycles, Recessions, and Financial Crises', 'This unit explains short-run expansions and contractions. Students learn how to identify cycles, interpret recession indicators, and understand crisis dynamics.', 7),
  ('9f99897d-b30c-4a7a-8b1e-9f8c5d99a060', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9ff88c17-4e2f-41e3-97c0-9244932bf8f1', 'subtopic'::public.curated_course_node_type, 'Business cycle phases', 'Students learn the vocabulary of expansions, peaks, recessions, troughs, and recoveries. This provides a timeline for interpreting macro news.', 0),
  ('0c8c8207-2c9f-4fa0-a11d-dc8621ae5b3f', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9f99897d-b30c-4a7a-8b1e-9f8c5d99a060', 'concept'::public.curated_course_node_type, 'Expansion', null, 0),
