  ('01716550-87c5-4f00-8eaf-8a215259beb2', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9f99897d-b30c-4a7a-8b1e-9f8c5d99a060', 'concept'::public.curated_course_node_type, 'Recovery', null, 4),
  ('d4c789d2-bc43-4b79-94cb-6f60627ea698', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9ff88c17-4e2f-41e3-97c0-9244932bf8f1', 'subtopic'::public.curated_course_node_type, 'Cycle indicators', 'Students learn how economists identify economic turning points. The gist is to use multiple indicators rather than one headline number.', 1);
