  ('84c1cd70-85f1-4b50-8fc3-efb2c4815d5c', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '9ff88c17-4e2f-41e3-97c0-9244932bf8f1', 'subtopic'::public.curated_course_node_type, 'Financial crises and policy response', 'Financial crises are severe because credit problems can spread across the real economy. Students learn the basic crisis mechanism and policy toolkit.', 3),
  ('2d31e7fd-ebdb-4005-8b4c-945500ab9d24', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '84c1cd70-85f1-4b50-8fc3-efb2c4815d5c', 'concept'::public.curated_course_node_type, 'Asset bubbles', null, 0),
