  ('a5c59890-2b23-408b-b305-0b2c4065576b', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '84c1cd70-85f1-4b50-8fc3-efb2c4815d5c', 'concept'::public.curated_course_node_type, 'Fiscal and monetary emergency responses', null, 4),
  ('5c2053e6-5212-40b9-ad5b-3504ff185a5d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', null, 'topic'::public.curated_course_node_type, 'International Trade, Comparative Advantage, and Capital Flows', 'This unit places the national economy in global context. Students learn why countries trade, why trade creates winners and losers, and how capital moves across borders.', 8),
  ('d52b8b6c-1621-4a9b-8017-5a3c40433e05', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5c2053e6-5212-40b9-ad5b-3504ff185a5d', 'subtopic'::public.curated_course_node_type, 'Comparative advantage', 'Students learn the core logic of gains from trade. The gist is that trade can be beneficial even when one country is more productive in everything.', 0),
