  ('d70824de-59a5-47b2-a7c7-20d015191934', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'd52b8b6c-1621-4a9b-8017-5a3c40433e05', 'concept'::public.curated_course_node_type, 'Specialization', null, 2),
  ('381d44b8-8eca-4a77-98d5-c643722b695d', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'd52b8b6c-1621-4a9b-8017-5a3c40433e05', 'concept'::public.curated_course_node_type, 'Terms of trade', null, 3),
  ('cb774323-6c2b-4f3d-a41b-ce5184050615', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5c2053e6-5212-40b9-ad5b-3504ff185a5d', 'subtopic'::public.curated_course_node_type, 'Trade patterns and policy', 'Students learn why countries export some goods and import others, and why trade policy is politically contested.', 1),
