  ('05a3b118-8445-4641-9760-1bb8c7127694', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', 'cb774323-6c2b-4f3d-a41b-ce5184050615', 'concept'::public.curated_course_node_type, 'Distributional effects', null, 3),
  ('7413cea5-877c-4ee9-ac44-faef57bcfdf5', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '5c2053e6-5212-40b9-ad5b-3504ff185a5d', 'subtopic'::public.curated_course_node_type, 'Capital flows', 'Capital flows connect saving and investment across countries. Students learn how cross-border finance affects growth, risk, and exchange rates.', 2),
  ('30dcb115-06fa-49ff-a08f-594ebd682cb0', 'a7b0d3f6-1e4c-4a15-8d20-5f9a4b7e6c03', '7413cea5-877c-4ee9-ac44-faef57bcfdf5', 'concept'::public.curated_course_node_type, 'Foreign direct investment', null, 0),
